+/* Scratch diagnostic only: aggregate scopes, no logging/waits. */
+#pragma once
+#include <stdint.h>
+namespace Tyra { namespace SnapshotBreakdown {
+enum Stage { SnapshotTotal, Preflight, ChainCopy, SecondPassInclusive, MutableCopy, NativeCountPass, NativeConvertInclusive, StageCount };
+struct Metrics {
+ uint64_t ticks[StageCount]={};
+ uint64_t snapshotCalls=0,snapshotSuccess=0,preflightTags=0,preflightRefs=0,secondPassTags=0,secondPassRefs=0;
+ uint64_t resolverQueries=0,immutableQueries=0,chainCopyAttemptQwords=0,chainCopyDoneQwords=0;
+ uint64_t mutableCopyAttemptQwords=0,mutableCopyDoneQwords=0,borrowedQwords=0,publishedCopiedQwords=0;
+ uint64_t nativeCountTags=0,nativeConvertTags=0,nativeConvertSuccess=0;
+};
+#ifndef TYRA_SNAPSHOT_BREAKDOWN
+#define TYRA_SNAPSHOT_BREAKDOWN 0
+#endif
+inline bool& gate(){static bool enabled=false;return enabled;}
+inline Metrics& data(){static Metrics metrics;return metrics;}
+inline uint32_t clock(){
+#if defined(_EE)
+ uint32_t t;asm volatile("mfc0 %0, $9":"=r"(t));return t;
+#else
+ return 0; // no host timing claims
+#endif
+}
+struct Scope {
+#if TYRA_SNAPSHOT_BREAKDOWN
+ Stage stage;uint32_t start;bool active;
+ explicit Scope(Stage s):stage(s),start(0),active(gate()){if(active)start=clock();}
+ ~Scope(){if(active)data().ticks[stage]+=uint32_t(clock()-start);}
+#else
+ explicit Scope(Stage){}
+#endif
+};
+inline void add(uint64_t& c,uint32_t n=1){
+#if TYRA_SNAPSHOT_BREAKDOWN
+ if(gate())c+=n;
+#else
+ (void)c;(void)n;
+#endif
+}
+inline void reset(){data()=Metrics{};}
+inline uint64_t secondPassExclusiveTicks(){return data().ticks[SecondPassInclusive]>=data().ticks[MutableCopy]?data().ticks[SecondPassInclusive]-data().ticks[MutableCopy]:0;}
+}}

